fn max_range_nearly_can_use(champ: &Entity, target: &Entity, tick: u64) -> u64   // battle.rs:2397
  let mut range: u64 = 0;                                   // 2398

  // ── 슬롯1: 평타 (battle.rs:2399~2404) ──
  if let Some(e) = champ.attack_effect {                    // Entity+0x4c0(casting) != -1
      if e.target.check(champ, target)                      // Entity+0x4b8, CastingTarget::check
         && champ.attack_cooldown() <= tick {               // entity.rs:1748 switch(ty)
          // switch(Entity+0x68) → 페이로드(Entity+0x70) 안의 attack_cooldown 오프셋:
          //   0 None / 3 Nexus  → 필드 없음 = 쿨다운 검사 자체를 건너뜀(무조건 통과)
          //   1 Minion→+0xb8  2 Tower→+0x110  4 Jungle,7 Ghoul→+0xe8  5 Epic,6 Serpen→+0x1f0
          //   8 SmallJiangshi,13 Champion→+0xb0  9 Bear→+0xc8  10 Eagle→+0xf0
          //   11 Revenant→+0xd8  12 Illusion→+0xd0
          range = total_range(e, champ, target);            // 2403. range 가 0 이라 max() 가 접혀 사라짐
      }
  }

  // ── 슬롯2: 스킬 (2407~2411) ──
  if let Some(e) = champ.skill_effect {                     // Entity+0x4f8 != -1
      if e.target.check(champ, target)                      // Entity+0x4f0
         && champ.skill_cooldown() <= tick {                // entity.rs:1775 — ty==13 일 때만 Entity+0xb8, 아니면 0
          range = max(range, total_range(e, champ, target)); // 2410
      }
  }

  // ── 슬롯3: 스킬2 (2414~2418) ──
  let s2 = if champ.level > 2 { &champ.skill2_effect } else { &DUMMY_NONE }; // entity.rs:1693
  if let Some(e) = s2 {                                     // (선택된 ptr)+0x30 != -1
      if e.target.check(champ, target)                      // (ptr)+0x28
         && champ.skill2_cooldown() <= tick {               // entity.rs:1790 — ty==13 일 때만 Entity+0xc0
          range = max(range, total_range(e, champ, target)); // 2417
      }
  }

  // ── 슬롯4: 궁 (2421~2425) ──
  let ul = if champ.level > 4 { &champ.ult_effect } else { &DUMMY_NONE };    // entity.rs:1701
  if let Some(e) = ul {                                     // (ptr)+0x30 != -1
      if e.target.check(champ, target)                      // (ptr)+0x28
         && champ.ult_cooldown() <= tick {                  // entity.rs:1805 — ty==13 일 때만 Entity+0xc8
          range = max(range, total_range(e, champ, target)); // 2424
      }
  }
  return range;                                             // 2429

// total_range = battle.rs 2403/2410/2417/2424 한 줄이 이렇게 펼쳐진다
fn total_range(e: &Effect, champ, target) -> u64 {
    // Effect::range (effect.rs:25~26)
    let base = champ.stat_buff_cached.range          // Entity+0x438
             + e.range                               // Effect+0x10
             + (champ.level - 1) * e.growth_range    // Entity+0x5c8, Effect+0x18
             + e.range_adjust(champ, target);        // 외부 호출(본체 없음)
    base + radius_of(champ) + radius_of(target)
}
fn radius_of(x: &Entity) -> u64 {                    // Entity::radius, entity.rs:1509~1515
    let mult = x.stat_buff_cached.radius_mult as i64; // Entity+0x470 (i32→sext)
    if mult == 0 { x.radius }                        // 1513
    else { x.radius * (mult + 100) / 100 }           // 1515, udiv
}

// ★주의 1: 4슬롯 모두 '레벨 성장항'과 'stat_buff_cached.range'는 champ 것만 쓴다. target 에서 읽는 건 radius(0x680)와 radius_mult(0x470) 둘뿐.
// ★주의 2: DUMMY_NONE = @anon.ff23c5838f81fa2a3acb125bb4b6e568.40 — 48바이트 undef + 0xFFFFFFFF(=casting None) 로 만든 상수 Effect. 레벨 미달 슬롯을 None 으로 만드는 장치다.
// ★주의 3: 슬롯1은 short-circuit 순서가 (Option 존재) → (target 적합) → (쿨다운) 이고, 슬롯2~4 도 동일하다. 쿨다운 게이트는 icmp ugt(cooldown, tick) 이 참이면 '건너뜀'이므로 통과 조건은 cooldown <= tick.
